@@ -0,0 +1,19 @@
+
+#[repr(C)]
+#[derive(Default)]
+struct FileTime { low: u32, high: u32 }
+#[link(name = "kernel32")]
+extern "system" {
+    fn GetCurrentProcess() -> *mut std::ffi::c_void;
+    fn GetProcessTimes(process: *mut std::ffi::c_void, creation: *mut FileTime, exit: *mut FileTime,
+        kernel: *mut FileTime, user: *mut FileTime) -> i32;
+}
+pub fn seconds() -> f64 {
+    let mut creation = FileTime::default(); let mut exit = FileTime::default();
+    let mut kernel = FileTime::default(); let mut user = FileTime::default();
+    // SAFETY: Windows pseudo-handle is valid and all output pointers refer to initialized FILETIMEs.
+    let ok = unsafe { GetProcessTimes(GetCurrentProcess(), &mut creation, &mut exit, &mut kernel, &mut user) };
+    assert_ne!(ok, 0);
+    let value = |time: FileTime| (u64::from(time.high) << 32) | u64::from(time.low);
+    (value(kernel) + value(user)) as f64 * 1e-7
+}
